import {equipment,muscles,patterns,levels,exerciseName,alternatives} from './exercise-catalog.js';
import {drawingPreview} from './xdraw-ui.js';
import {trainingTemplates,calendarDate,blocksForDay} from './training-templates.js';
const methods=['standard','drop','superset','triset','giant','circuit','restPause','pyramid','cluster','tempo','amrap','custom'];
const phases=['base','strength','hypertrophy','endurance','deload','custom'];
const tabs=['catalog','builder','live','progress'];
const views=new Map();
const getView=id=>{if(!views.has(id))views.set(id,{tab:'catalog',query:'',equipment:[],muscle:'',level:'',secondary:'',page:0,plan:null,edit:null,block:null,week:1,day:1});return views.get(id)};
export function trainingUI(userId,op,value){
  const v=getView(userId);
  if(op==='tab'&&tabs.includes(value))v.tab=value;
  if(op==='plan'){v.plan=value;v.block=null;v.tab='builder';v.week=1;v.day=1}
  if(op==='week'){v.week=Math.max(1,v.week+Number(value));v.block=null}
  if(op==='day'){v.day=Math.max(1,Math.min(7,Number(value)));v.block=null}
  if(op==='edit')v.edit=value;
  if(op==='block')v.block=value;
  if(op==='page')v.page=Math.max(0,v.page+Number(value));
  if(op==='filter')Object.assign(v,{...value,page:0});
}
export function resetTrainingUI(){views.clear()}
// Keep the blank-program draft scoped to the current identity and across UI redraws.
export function rememberTrainingDraft(userId,form){
  if(!userId||!form?.hasAttribute('data-plan-draft'))return;
  getView(userId).createDraft=Object.fromEntries(['title','goal','startDate','weeks','daysPerWeek','unit','notes'].map(k=>[k,form.elements.namedItem(k)?.value??'']));
}
export function clearTrainingDraft(userId){if(userId)delete getView(userId).createDraft}
const factor=u=>u==='lb'?2.2046226218:1;
const toDisplay=(kg,u)=>Math.round(kg*factor(u)*100)/100;
const toKg=(weight,u)=>Math.round(Number(weight)/factor(u)*1000)/1000;
const td=()=>new Date().toISOString().slice(0,10);
const field=(t,h,n,k,value='',type='text',extra='')=>`<label>${t(k)}<input name="${n}" type="${type}" value="${h(value)}" ${extra}></label>`;
const area=(t,h,n,k,value='',max=1000)=>`<label>${t(k)}<textarea name="${n}" maxlength="${max}">${h(value)}</textarea></label>`;
const select=(t,h,n,k,opts,value='',required=true)=>`<label>${t(k)}<select name="${n}" ${required?'required':''}>${opts.map(([a,b])=>`<option value="${h(a)}" ${String(value)===String(a)?'selected':''}>${h(b)}</option>`).join('')}</select></label>`;
const hidden=(h,k,v)=>`<input type="hidden" name="${k}" value="${h(v)}">`;
const form=(t,h,op,body,id='',label='save')=>`<form class="stack training-form" data-form="training"${op==='planCreate'?' id="training-create-plan" data-plan-draft':op==='planUpdate'?' id="training-edit-plan"':''}>${hidden(h,'operation',op)}${id?hidden(h,'id',id):''}${body}<button type="submit" class="primary">${t(label)}</button></form>`;
const b=(t,h,btn,key,action,id='',extra='')=>btn(t(key),action,`data-id="${h(id)}" ${extra}`,'secondary');
const act=(t,h,btn,key,op,id='',extra='')=>b(t,h,btn,key,'trainingAction',id,`data-op="${op}" ${extra}`);
const ui=(t,h,btn,key,op,id)=>b(t,h,btn,key,'trainingUI',id,`data-op="${op}"`);
const choices=(t,list)=>list.map(x=>[x,t('train_'+x)]);
const empty=t=>`<p class="empty">${t('noItems')}</p>`;
const label=(t,k)=>t('train_'+k);
const itemName=(d,id,lang)=>exerciseName(d.catalog.find(e=>e.id===id),lang)||id;
function catalogForm(t,h,r){
  return ['ar','en','sv'].map(l=>field(t,h,'name_'+l,'lang_'+l,r?.names[l],'text','required maxlength="100"')+area(t,h,'note_'+l,'train_cues',r?.notes[l],1000)+area(t,h,'mistake_'+l,'train_mistakes',r?.content?.mistakes?.[l],1000)+area(t,h,'safety_'+l,'train_safety',r?.content?.safety?.[l],1000)).join('')+select(t,h,'equipment','train_equipment',choices(t,equipment),r?.equipment||'bodyweight')+select(t,h,'muscle','train_muscle',choices(t,muscles),r?.muscle||'chest')+select(t,h,'pattern','train_pattern',choices(t,patterns),r?.pattern||'horizontalPush')+select(t,h,'level','train_level',choices(t,levels),r?.level||'beginner')+`<fieldset class="training-filter"><legend>${t('train_stretchTargets')}</legend>${muscles.filter(m=>m!=='stretch').map(m=>`<label class="check-row"><input type="checkbox" name="target" value="${m}" ${r?.secondary?.includes(m)?'checked':''}>${label(t,m)}</label>`).join('')}</fieldset>`+field(t,h,'reference','train_mediaReference',r?.media?.reference,'text','maxlength="200"')+field(t,h,'rights','train_mediaRights',r?.media?.rights,'text','maxlength="200"');
}
const mediaUrl=(id,slot)=>'/api/training-media?exercise='+encodeURIComponent(id)+'&slot='+slot;
function mediaPanel(t,h,btn,e,lang,admin){
  const content=e.content||{},assets=content.assets||{},status=content.status||'draft';
  if(!admin&&status!=='published')return `<small class="muted">${t('train_mediaPending')}</small>`;
  const media=(admin?drawingPreview(h,e.id,lang,exerciseName(e,lang)):'')+(content.origin==='starterDraft'?`<p class="notice">${t('train_starterDraft')}</p>`:'')+['start','end','video'].map(slot=>{const src=h(mediaUrl(e.id,slot));return assets[slot]?`<figure class="training-media"><figcaption>${label(t,'media_'+slot)}</figcaption>${slot==='video'?`<video controls preload="none" playsinline src="${src}"></video>`:`<img loading="lazy" alt="${h(exerciseName(e,lang)+' '+label(t,'media_'+slot))}" src="${src}">`}</figure>`:''}).join('');
  return `<details ${admin&&status!=='published'?'':' '}><summary>${t('train_mediaDetails')}${admin?' · '+label(t,'content_'+status):''}</summary><div class="stack">${media}${e.notes?.[lang]?`<p>${h(e.notes[lang])}</p>`:''}${content.mistakes?.[lang]?`<p><b>${t('train_mistakes')}</b> ${h(content.mistakes[lang])}</p>`:''}${content.safety?.[lang]?`<p><b>${t('train_safety')}</b> ${h(content.safety[lang])}</p>`:''}${e.media?`<small>${h(e.media.reference)} · ${h(e.media.rights)}</small>`:''}${admin?`<p class="notice">${t('train_mediaUploadHint')}</p>${['start','end','video'].map(slot=>`<form class="stack training-form" data-form="trainingMedia">${hidden(h,'id',e.id)}${hidden(h,'slot',slot)}<label>${label(t,'media_'+slot)}<input type="file" name="file" accept="${slot==='video'?'video/mp4,video/webm':'image/jpeg,image/png,image/webp'}" required></label><button type="submit" class="secondary">${t('train_uploadMedia')}</button></form>`).join('')}<div class="row wrap">${status==='draft'?act(t,h,btn,'train_submitReview','contentSubmit',e.id):''}${status==='review'?act(t,h,btn,'train_publishContent','contentPublish',e.id):''}${status!=='draft'?act(t,h,btn,'train_returnDraft','contentReturn',e.id):''}</div>`:''}</div></details>`;
}
function catalogPage({state,t,h,btn,lang,v}){
  const d=state.training;
  const visible=d.catalog.filter(r=>(!v.equipment.length||v.equipment.includes(r.equipment))&&(!v.muscle||r.muscle===v.muscle)&&(!v.level||r.level===v.level)&&(!v.secondary||r.secondary?.includes(v.secondary))&&(!v.query||Object.values(r.names).some(n=>n.toLowerCase().includes(v.query.toLowerCase()))));
  const last=Math.max(0,Math.ceil(visible.length/24)-1);v.page=Math.min(v.page,last);
  const rows=visible.slice(v.page*24,(v.page+1)*24);
  const editor=v.edit&&d.canAdmin?(v.edit==='new'?null:d.catalog.find(r=>r.id===v.edit)):null;
  return `<section class="card stack"><div class="row space wrap"><h2>${t('exerciseLibrary')}</h2><span class="badge green">${visible.length} / ${d.catalog.length}</span></div><form class="stack" data-form="trainingFilter">${field(t,h,'query','train_search',v.query,'search','maxlength="100"')}<fieldset class="training-filter"><legend>${t('train_equipment')}</legend>${equipment.map(e=>`<label class="check-row"><input name="equipment" type="checkbox" value="${e}" ${v.equipment.includes(e)?'checked':''}>${label(t,e)}</label>`).join('')}</fieldset><div class="grid">${select(t,h,'muscle','train_muscle',[['',t('all')],...choices(t,muscles)],v.muscle,false)}${select(t,h,'level','train_level',[['',t('all')],...choices(t,levels)],v.level,false)}${select(t,h,'secondary','train_secondary',[['',t('all')],...choices(t,muscles)],v.secondary,false)}</div><button type="submit" class="secondary">${t('train_search')}</button></form>${d.canAdmin?ui(t,h,btn,'create','edit','new'):''}${d.canAdmin&&v.edit?`<div class="rule stack"><h3>${t(v.edit==='new'?'create':'wellnessEdit')}</h3>${form(t,h,editor?'catalogUpdate':'catalogCreate',catalogForm(t,h,editor),editor?.id)}${ui(t,h,btn,'train_close','edit','')}</div>`:''}<div class="grid training-cards">${rows.map(e=>`<article class="card stack"><span class="badge">${label(t,e.equipment)} · ${label(t,e.level)}</span><h3>${h(exerciseName(e,lang))}</h3><small>${label(t,e.muscle)} · ${label(t,e.pattern)}</small>${e.secondary?.length?`<small>${t('train_secondary')}: ${e.secondary.map(m=>label(t,m)).join(' · ')}</small>`:''}${e.archived?`<span class="badge gold">${t('train_archived')}</span>`:''}${mediaPanel(t,h,btn,e,lang,d.canAdmin)}<details><summary>${t('train_alternatives')}</summary>${alternatives(d.catalog,e).slice(0,12).map(x=>`<p>${h(exerciseName(x,lang))} · ${label(t,x.equipment)}</p>`).join('')||empty(t)}</details>${d.canAdmin?`<div class="row wrap">${ui(t,h,btn,'wellnessEdit','edit',e.id)}${act(t,h,btn,e.archived?'train_restore':'train_archive',e.archived?'catalogRestore':'catalogArchive',e.id)}</div>`:''}</article>`).join('')||empty(t)}</div><div class="row space wrap">${v.page?ui(t,h,btn,'train_previous','page','-1'):''}<small>${v.page+1} / ${last+1}</small>${v.page<last?ui(t,h,btn,'train_next','page','1'):''}</div></section>`;
}
const planTitle=(t,h,id,k,value='')=>`<label for="${h(id)}">${t(k)}</label><input id="${h(id)}" name="title" type="text" value="${h(value)}" required maxlength="100" autocomplete="off">`;
function planFields(t,h,p,draft){const values=p||draft;return planTitle(t,h,p?'training-edit-title':'training-new-title',p?'train_editTitle':'train_title',values?.title)+field(t,h,'goal','train_goal',values?.goal,'text','maxlength="80"')+field(t,h,'startDate','clubStart',values?.startDate||td(),'date','required')+field(t,h,'weeks','train_weeks',values?.weeks??4,'number','required min="1" max="52"')+field(t,h,'daysPerWeek','train_days',values?.daysPerWeek??3,'number','required min="1" max="7"')+select(t,h,'unit','train_unit',[['kg','kg'],['lb','lb']],values?.unit||'kg')+area(t,h,'notes','train_notes',values?.notes);}
function blockFields(t,h,p,d,lang,block,v){
  const available=d.catalog.filter(x=>!x.archived);
  const picker=(i,value)=>`<label>${t('train_exercise')}<select name="exercise${i}" data-exercise-picker><option value="">${t('train_none')}</option>${available.map(x=>`<option value="${h(x.id)}" data-query="${h(Object.values(x.names).join(' ').toLowerCase())}" data-equipment="${h(x.equipment)}" data-muscle="${h(x.muscle)}" data-level="${h(x.level)}" ${value===x.id?'selected':''}>${h(exerciseName(x,lang)+' · '+label(t,x.equipment))}</option>`).join('')}</select></label>`;
  const filters=`<fieldset class="training-filter" data-picker-filters><legend>${t('train_pickExercise')}</legend>${field(t,h,'pickerQuery','train_search','','search','maxlength="100"')}${select(t,h,'pickerEquipment','train_equipment',[['',t('all')],...choices(t,equipment)],'',false)}${select(t,h,'pickerMuscle','train_muscle',[['',t('all')],...choices(t,muscles)],'',false)}${select(t,h,'pickerLevel','train_level',[['',t('all')],...choices(t,levels)],'',false)}<output data-picker-count>${available.length}</output></fieldset>`;
  const input=(n,k,val,min,max,step=1)=>field(t,h,n,k,val,'number',`min="${min}" max="${max}" step="${step}"`);
  return hidden(h,'unit',p.unit)+(block?hidden(h,'blockId',block.id):'')+select(t,h,'method','train_method',choices(t,methods),block?.method||'standard')+field(t,h,'name','train_customName',block?.name,'text','maxlength="80"')+select(t,h,'phase','train_phase',choices(t,phases),block?.phase||'base')+input('day','train_day',block?.day||v.day,1,7)+input('weekFrom','train_weekFrom',block?.weekFrom||v.week,1,p.weeks)+input('weekTo','train_weekTo',block?.weekTo||v.week,1,p.weeks)+input('rounds','train_rounds',block?.rounds||3,1,20)+input('rest','train_groupRest',block?.rest??60,0,3600)+select(t,h,'section','train_section',choices(t,['warmup','work','cooldown']),block?.section||(block?.warmup?'warmup':'work'))+`<p class="notice">${t('train_methodHint')}</p>`+filters+Array.from({length:8},(_,i)=>{
    const r=block?.items[i];
    return `<details class="rule" ${i===0||r?'open':''}><summary>${t('train_exercise')} ${i+1}${r?' · '+h(itemName(d,r.exerciseId,lang)):''}</summary><div class="stack">${picker(i,r?.exerciseId)}<div class="grid">${input('kg'+i,'train_load',toDisplay(r?.kg??0,p.unit),0,p.unit==='lb'?2205:1000,0.01)}${input('reps'+i,'train_reps',r?.reps||10,1,500)}${input('duration'+i,'train_duration',r?.duration??0,0,7200)}${input('rest'+i,'train_rest',r?.rest??0,0,3600)}${input('rpe'+i,'train_rpe',r?.rpe??'',1,10,0.5)}${input('rir'+i,'train_rir',r?.rir??'',0,10,0.5)}</div>${select(t,h,'side'+i,'train_side',[['both',label(t,'both')],['each',label(t,'each')]],r?.side||'both')}${field(t,h,'tempo'+i,'train_tempo',r?.tempo,'text','placeholder="3-1-1-0" maxlength="20"')}${field(t,h,'weights'+i,'train_weightSequence',r?.weights.map(x=>toDisplay(x,p.unit)).join(', ')||'','text','maxlength="160"')}${input('segments'+i,'train_segments',r?.segments>1?r.segments:2,2,10)}${input('segmentRest'+i,'train_segmentRest',r?.segmentRest||15,1,300)}</div></details>`;
  }).join('');
}
function blockSummary(t,h,d,p,x,lang){return `<div><b>${label(t,x.method)}${x.name?' · '+h(x.name):''}</b><br><small>${t('train_day')} ${x.day} · ${t('train_weeks')} ${x.weekFrom}–${x.weekTo} · ${label(t,x.phase)} · ${x.rounds} ×</small></div>${x.items.map(i=>`<p>${h(itemName(d,i.exerciseId,lang))} · ${toDisplay(i.kg,p.unit)} ${p.unit} × ${i.reps}${i.weights.length?' · '+i.weights.map(k=>toDisplay(k,p.unit)).join(' → '):''}</p>`).join('')}`;
}
function templatesPanel(t,h,d){
  const list=trainingTemplates.filter(x=>x.days.every(day=>day.exercises.every(id=>d.catalog.some(r=>r.id===id&&!r.archived)))&&['march-in-place','child-pose'].every(id=>d.catalog.some(r=>r.id===id&&!r.archived)));
  return `<details data-template-panel><summary>${t('train_templates')}</summary><p class="notice">${t('train_templateNotice')}</p><div class="grid">${select(t,h,'templateGoal','train_goal',[['',t('all')],...choices(t,['general','strength','hypertrophy'])],'',false)}${select(t,h,'templateLevel','train_level',[['',t('all')],...choices(t,['beginner','intermediate'])],'',false)}</div>${list.map(x=>`<details class="rule" data-template data-level="${x.level}" data-goal="${x.goal}"><summary>${label(t,x.id)} · ${label(t,x.level)} · ${label(t,x.goal)} · ${x.daysPerWeek} ${t('train_days')}</summary>${form(t,h,'planCreateTemplate',hidden(h,'templateId',x.id)+planTitle(t,h,'training-template-title-'+x.id,'train_templateTitle',label(t,x.id))+hidden(h,'goal',label(t,x.goal))+field(t,h,'startDate','clubStart',td(),'date','required')+field(t,h,'weeks','train_weeks',4,'number','required min="1" max="52"')+select(t,h,'unit','train_unit',[['kg','kg'],['lb','lb']],'kg'),'', 'train_useTemplate')}</details>`).join('')||empty(t)}</details>`;
}
function calendarPanel(t,h,btn,d,p,lang,v,active){
  v.week=Math.max(1,Math.min(p.weeks,v.week));
  const week=v.week,day=v.day,rows=blocksForDay(p.blocks,week,day),weeks=Array.from({length:p.weeks},(_,i)=>[i+1,String(i+1)]),days=Array.from({length:7},(_,i)=>[i+1,String(i+1)]);
  const dateLabel=i=>new Intl.DateTimeFormat(lang,{weekday:'short',month:'short',day:'numeric',timeZone:'UTC'}).format(new Date(calendarDate(p.startDate,week,i)+'T00:00:00Z'));
  const dayField=(n,k,value)=>select(t,h,n,k,days,value),weekField=(n,k,value)=>select(t,h,n,k,weeks,value);
  return `<section class="rule stack"><div class="row space wrap"><h3>${t('train_calendar')}</h3><div class="row wrap">${week>1?ui(t,h,btn,'train_previous','week','-1'):''}<span class="badge">${t('train_week')} ${week}/${p.weeks}</span>${week<p.weeks?ui(t,h,btn,'train_next','week','1'):''}</div></div><div class="training-calendar">${days.map(([i])=>{const blocks=blocksForDay(p.blocks,week,i);return `<button type="button" class="secondary training-day ${i===day?'selected':''}" aria-pressed="${i===day}" data-action="trainingUI" data-op="day" data-id="${i}"><b>${t('train_day')} ${i}</b><small>${h(dateLabel(i))}</small><span>${blocks.length?blocks.length+' '+t('train_blocks'):t('train_restDay')}</span></button>`}).join('')}</div><h4>${h(dateLabel(day))} · ${rows.length?rows.length+' '+t('train_blocks'):t('train_restDay')}</h4>${rows.map(x=>`<div class="row wrap"><span class="badge">${label(t,x.section||(x.warmup?'warmup':'work'))}</span><span>${x.items.map(i=>h(itemName(d,i.exerciseId,lang))).join(' · ')}</span></div>`).join('')}${p.mine&&!active&&rows.length?form(t,h,'start',hidden(h,'week',week)+hidden(h,'day',day),p.id,'train_start'):''}${rows.length?form(t,h,'dayRest',hidden(h,'week',week)+hidden(h,'day',day),p.id,'train_makeRest'):''}<details><summary>${t('train_copyDay')}</summary>${form(t,h,'dayCopy',hidden(h,'sourceWeek',week)+hidden(h,'sourceDay',day)+weekField('targetWeek','train_targetWeek',week)+dayField('targetDay','train_targetDay',day===7?1:day+1),p.id,'train_copyDay')}</details><details><summary>${t('train_copyWeek')}</summary>${form(t,h,'weekCopy',hidden(h,'sourceWeek',week)+weekField('targetWeek','train_targetWeek',week===p.weeks?1:week+1),p.id,'train_copyWeek')}</details><p class="muted">${t('train_copyHint')}</p></section>`;
}
export function updateTrainingPicker(form){
  if(!form?.querySelector('[data-picker-filters]'))return;
  const query=(form.elements.pickerQuery?.value||'').trim().toLowerCase(),eq=form.elements.pickerEquipment?.value,mu=form.elements.pickerMuscle?.value,level=form.elements.pickerLevel?.value;
  let total=0;const matches=o=>(!query||o.dataset.query.includes(query))&&(!eq||o.dataset.equipment===eq)&&(!mu||o.dataset.muscle===mu)&&(!level||o.dataset.level===level);
  for(const [i,s] of Array.from(form.querySelectorAll('[data-exercise-picker]')).entries())for(const o of s.options){if(!o.value)continue;const match=matches(o);if(!i&&match)total++;o.hidden=!match&&!o.selected;o.disabled=!match&&!o.selected}
  form.querySelector('[data-picker-count]').textContent=String(total);
}
export function updateTemplateFilter(panel){
  if(!panel)return;const goal=panel.querySelector('[name=templateGoal]').value,level=panel.querySelector('[name=templateLevel]').value;
  for(const row of panel.querySelectorAll('[data-template]'))row.hidden=!!((goal&&row.dataset.goal!==goal)||(level&&row.dataset.level!==level));
}
function builderPage({state,t,h,btn,lang,v}){
  const d=state.training,p=d.plans.find(p=>p.id===v.plan)||d.plans[0],active=d.sessions?.some(s=>s.status==='active');
  if(!d.enabled)return `<div class="notice">${t('train_testNotice')}</div>${btn(t('health'),'nav','data-id="health"','secondary')}`;
  const block=p?.blocks.find(x=>x.id===v.block);
  return `<div class="stack"><section class="card stack"><h2>${t('trainingBuilder')}</h2><details id="training-create-panel" ${!d.plans.length||v.createDraft?'open':''}><summary>${t('train_newProgram')}</summary>${form(t,h,'planCreate',planFields(t,h,null,v.createDraft),'','train_createProgram')}</details>${templatesPanel(t,h,d)}<div class="grid training-cards">${d.plans.map(x=>`<button class="card quick ${p?.id===x.id?'active':''}" data-action="trainingUI" data-op="plan" data-id="${h(x.id)}"><b>${h(x.title)}</b><small>${x.weeks} ${t('train_weeks')} · ${x.ownerName?h(x.ownerName):''} ${x.archived?t('train_archived'):''}</small></button>`).join('')||empty(t)}</div></section>${p?`<section class="card stack"><div class="row space wrap"><h2>${h(p.title)}</h2><span class="badge">${p.mine?t('train_personal'):h(p.ownerName)} · v${p.revision}</span></div><p>${h(p.goal)} · ${p.daysPerWeek} ${t('train_days')} · ${h(p.startDate)}</p>${p.archived?act(t,h,btn,'train_restore','planRestore',p.id):`<details><summary>${t('wellnessEdit')}</summary>${form(t,h,'planUpdate',planFields(t,h,p),p.id)}</details><div class="row wrap">${p.mine?act(t,h,btn,'train_copy','planCopy',p.id):''}${act(t,h,btn,'train_archive','planArchive',p.id)}</div>${d.canCoach&&p.mine&&d.links.length?form(t,h,'planAssign',select(t,h,'linkId','train_assign',d.links.map(x=>[x.id,x.name])),p.id,'train_assign'):''}${calendarPanel(t,h,btn,d,p,lang,v,active)}<h3>${t('train_blocks')}</h3>${p.blocks.map((x,i)=>`<article class="rule stack training-block" draggable="true" data-drag-block="${h(x.id)}" data-plan="${h(p.id)}">${blockSummary(t,h,d,p,x,lang)}<div class="row wrap">${i?act(t,h,btn,'train_up','blockMove',p.id,`data-block="${h(x.id)}" data-direction="-1"`):''}${i<p.blocks.length-1?act(t,h,btn,'train_down','blockMove',p.id,`data-block="${h(x.id)}" data-direction="1"`):''}${ui(t,h,btn,'wellnessEdit','block',x.id)}${act(t,h,btn,'remove','blockRemove',p.id,`data-block="${h(x.id)}"`)}</div></article>`).join('')||empty(t)}${ui(t,h,btn,'train_addBlock','block','new')}${v.block?`<div class="rule stack"><h3>${t(block?'wellnessEdit':'train_addBlock')} (${p.unit})</h3>${form(t,h,block?'blockUpdate':'blockAdd',blockFields(t,h,p,d,lang,block,v),p.id)}${ui(t,h,btn,'train_close','block','')}</div>`:''}`}</section>`:''}</div>`;
}
function livePage({state,t,h,btn,lang}){
  const d=state.training,r=d.sessions?.find(x=>x.status==='active');
  if(!r)return `<section class="card stack"><h2>${t('trainingLive')}</h2><p>${t('train_noActive')}</p>${ui(t,h,btn,'trainingBuilder','tab','builder')}</section>`;
  const step=r.steps[r.cursor],base=hidden(h,'sessionId',r.id)+hidden(h,'index',r.cursor)+hidden(h,'unit',r.unit);
  return `<section class="card stack training-live"><div class="row space wrap"><h2>${h(r.planTitle)}</h2><span class="badge green">${r.cursor} / ${r.steps.length}</span></div><progress value="${r.cursor}" max="${r.steps.length}"></progress>${r.restUntil?`<div class="stat-box"><small>${t('train_rest')}</small><br><output class="stat green" data-training-rest="${r.restUntil}">—</output></div>`:''}${step?`<p class="muted">${t('train_remaining')}: ${r.steps.length-r.cursor} · ${label(t,step.warmup?'warmup':step.cooldown?'cooldown':'work')}</p><h2>${h(exerciseName(step,lang))}</h2><div class="row wrap"><span class="badge">${label(t,step.method)}</span><span class="badge">${t('train_round')} ${step.round} · ${step.stage}</span><span class="badge">${label(t,step.side)}</span></div><div class="grid grid3"><div class="stat-box"><small>${t('train_load')}</small><br><b>${toDisplay(step.kg,r.unit)} ${r.unit}</b></div><div class="stat-box"><small>${t('train_reps')}</small><br><b>${step.reps}</b></div><div class="stat-box"><small>${t('train_tempo')}</small><br><b>${h(step.tempo||'—')}</b></div></div>${step.duration?`<p>${t('train_duration')}: ${step.duration} s</p>`:''}${step.rpe!==null||step.rir!==null?`<p>${t('train_rpe')}: ${step.rpe??'—'} · ${t('train_rir')}: ${step.rir??'—'}</p>`:''}${r.steps[r.cursor+1]?`<p class="muted">${t('train_next')}: ${h(exerciseName(r.steps[r.cursor+1],lang))}</p>`:''}${form(t,h,'log',base+field(t,h,'kg','train_load',toDisplay(step.kg,r.unit),'number','required min="0" max="2204" step="0.01"')+field(t,h,'reps','train_reps',step.reps,'number','required min="0" max="500"')+field(t,h,'duration','train_duration',step.duration,'number','required min="0" max="7200"')+field(t,h,'rpe','train_rpe','','number','min="1" max="10" step="0.5"')+field(t,h,'rir','train_rir','','number','min="0" max="10" step="0.5"'),'','train_log')}${act(t,h,btn,'train_skip','skip',r.id,`data-index="${r.cursor}"`)}${alternatives(d.catalog,{id:step.exerciseId,...step}).length?form(t,h,'replace',base+select(t,h,'exerciseId','train_alternatives',alternatives(d.catalog,{id:step.exerciseId,...step}).map(e=>[e.id,exerciseName(e,lang)+' · '+label(t,e.equipment)])),'','train_replace'):''}`:`<h3>${t('train_finish')}</h3>${form(t,h,'finish',hidden(h,'sessionId',r.id)+field(t,h,'rating','train_rating','','number','min="1" max="5"')+area(t,h,'note','train_notes','',500),'','train_finish')}`}${act(t,h,btn,'train_cancel','cancel',r.id)}</section>`;
}
function progressStats(t,h,x,lang,unit='kg'){return `<div class="grid grid3"><div class="stat-box"><b>${x.sessions}</b><br><small>${t('train_sessions')}</small></div><div class="stat-box"><b>${x.sets}</b><br><small>${t('train_sets')}</small></div><div class="stat-box"><b>${toDisplay(x.volume,unit)} ${unit}</b><br><small>${t('train_volume')}</small></div></div><h3>${t('train_records')}</h3>${x.exercises.map(e=>`<div class="rule"><b>${h(exerciseName(e,lang))}</b><br><small>PR: ${toDisplay(e.maxKg,unit)} ${unit} · ${e.maxReps} ${t('train_reps')} · ${t('train_volume')}: ${toDisplay(e.volume,unit)} ${unit}</small><details><summary>${t('train_history')}</summary>${e.recent.map(r=>`<p>${h(new Date(r.at).toISOString().slice(0,10))} · ${toDisplay(r.kg,unit)} ${unit} × ${r.reps}</p>`).join('')}</details></div>`).join('')||empty(t)}<h3>${t('train_muscleVolume')}</h3>${Object.entries(x.muscleVolume).map(([m,v])=>`<div class="row space"><span>${label(t,m)}</span><b>${toDisplay(v,unit)} ${unit}</b></div>`).join('')||empty(t)}<h3>${t('train_weekly')}</h3>${Object.entries(x.weekly).slice(0,30).map(([date,count])=>`<div class="row space"><span>${h(date)}</span><b>${count}</b></div>`).join('')||empty(t)}<h3>${t('train_monthly')}</h3>${Object.entries(x.monthly).slice(0,12).map(([date,count])=>`<div class="row space"><span>${h(date)}</span><b>${count}</b></div>`).join('')||empty(t)}${x.adherence?`<h3>${t('train_adherence')}</h3>${x.adherence.map(a=>`<div class="rule"><b>${h(a.title)}</b> · ${a.completed}/${a.planned} ${a.planned?Math.round(a.completed/a.planned*100):0}%</div>`).join('')||empty(t)}`:''}`}
function progressPage({state,t,h,btn,lang}){
  const d=state.training;if(!d.enabled)return `<div class="notice">${t('train_testNotice')}</div>`;
  return `<div class="stack"><section class="card stack"><h2>${t('trainingProgress')}</h2>${progressStats(t,h,d.progress,lang)}<h3>${t('train_suggestions')}</h3><p class="notice">${t('train_suggestionNotice')}</p>${act(t,h,btn,d.settings.progression?'programDisable':'programEnable','settings','',`data-progression="${!d.settings.progression}"`)}${d.suggestions.map(a=>`<div class="rule row wrap"><b class="grow">${h(itemName(d,a.exerciseId,lang))} · ${a.kg} kg</b>${act(t,h,btn,'train_apply','progressApply',a.planId,`data-block="${h(a.blockId)}" data-item="${a.itemIndex}" data-kg="${a.kg}"`)}</div>`).join('')||empty(t)}<h3>${t('train_history')}</h3>${d.sessions.filter(r=>r.status!=='active').slice().reverse().map(r=>`<article class="rule stack"><b>${h(r.planTitle)}</b><small>${h(new Date(r.endedAt).toISOString().slice(0,10))} · ${label(t,r.status)} · ${r.logs.filter(l=>!l.skipped).length}/${r.steps.length} · ${r.rating??'—'}</small><p>${h(r.note)}</p><details><summary>${t('train_history')}</summary>${r.logs.map(l=>`<div class="rule"><b>${h(exerciseName(r.steps[l.index],lang))}</b> · ${l.skipped?t('train_skip'):toDisplay(l.kg,r.unit)+' '+r.unit+' × '+l.reps}</div>`).join('')}</details>${act(t,h,btn,'remove','sessionDelete',r.id)}</article>`).join('')||empty(t)}</section>${(d.shared||[]).map(x=>`<section class="card stack"><h2>${t('train_shared')} · ${h(x.name)}</h2>${progressStats(t,h,x.progress,lang)}</section>`).join('')}</div>`;
}
export function trainingPage(args){
  const {state,t,h,btn}=args,d=state.training;if(!d)return '';
  const v=getView(state.me.id);
  const permitted=d.enabled?tabs:['catalog'];
  if(!permitted.includes(v.tab))v.tab='catalog';
  return `<div class="stack"><div class="hero workspace-hero"><span class="eyebrow">MUSCLIVO LIVE / TRAIN PRO</span><h1>${t('trainingPro')}</h1><p>${t('train_testNotice')}</p></div><div class="row wrap">${permitted.map(x=>btn(t('train_tab_'+x),'trainingUI',`data-op="tab" data-id="${x}" aria-pressed="${x===v.tab}"`,x===v.tab?'primary':'secondary')).join('')}${!d.enabled&&!d.canAdmin?btn(t('health'),'nav','data-id="health"','secondary'):''}</div>${({catalog:catalogPage,builder:builderPage,live:livePage,progress:progressPage})[v.tab]({...args,v})}</div>`;
}
const nullable=v=>v===''||v===undefined?null:Number(v);
export function trainingPayload(data){
  const d={...data},op=d.operation;
  if(['catalogCreate','catalogUpdate'].includes(op)){d.names=Object.fromEntries(['ar','en','sv'].map(l=>[l,d['name_'+l]]));d.notes=Object.fromEntries(['ar','en','sv'].map(l=>[l,d['note_'+l]||'']));d.mistakes=Object.fromEntries(['ar','en','sv'].map(l=>[l,d['mistake_'+l]||'']));d.safety=Object.fromEntries(['ar','en','sv'].map(l=>[l,d['safety_'+l]||'']));d.media=d.reference||d.rights?{reference:d.reference,rights:d.rights}:null;}
  if(['planCreate','planUpdate','planCreateTemplate'].includes(op)){d.weeks=Number(d.weeks);if(op!=='planCreateTemplate')d.daysPerWeek=Number(d.daysPerWeek)}
  if(['blockAdd','blockUpdate'].includes(op)){
    for(const k of ['rounds','day','weekFrom','weekTo','rest'])d[k]=Number(d[k]);d.warmup=d.warmup==='on';d.items=[];
    for(let i=0;i<8;i++)if(d['exercise'+i])d.items.push({exerciseId:d['exercise'+i],kg:toKg(d['kg'+i],d.unit),reps:Number(d['reps'+i]),duration:Number(d['duration'+i]),rest:Number(d['rest'+i]),rpe:nullable(d['rpe'+i]),rir:nullable(d['rir'+i]),side:d['side'+i],tempo:d['tempo'+i],weights:String(d['weights'+i]||'').split(',').map(x=>x.trim()).filter(Boolean).map(x=>toKg(x,d.unit)),segments:Number(d['segments'+i]),segmentRest:Number(d['segmentRest'+i])});
  }
  if(op==='start'||op==='dayRest'){d.week=Number(d.week);d.day=Number(d.day)}
  if(op==='dayRest')d.confirm=d.confirm===true;
  if(op==='dayCopy'||op==='weekCopy'){d.sourceWeek=Number(d.sourceWeek);d.targetWeek=Number(d.targetWeek);if(op==='dayCopy'){d.sourceDay=Number(d.sourceDay);d.targetDay=Number(d.targetDay)}}
  if(['log','replace'].includes(op))d.index=Number(d.index);
  if(op==='log'){d.kg=toKg(d.kg,d.unit);d.reps=Number(d.reps);d.duration=Number(d.duration);d.rpe=nullable(d.rpe);d.rir=nullable(d.rir)}
  if(op==='finish')d.rating=nullable(d.rating);
  return d;
}
export function updateTrainingTimer(root=document){for(const el of root.querySelectorAll('[data-training-rest]')){const s=Math.max(0,Math.ceil((Number(el.dataset.trainingRest)-Date.now())/1000));el.textContent=Math.floor(s/60)+':'+String(s%60).padStart(2,'0')}}
